import {MODES,PRIORITIES,DEFAULTS,SOURCES,buildCandidates,generate,evaluate,totals,validSettings,cleanStopName} from './engine.js?v=nextstop-14';
import {initializeTravel} from './travel.js?v=nextstop-14';
import {environmentDetail,addEnvironmentLayers,ENVIRONMENT_SOURCES} from './environment.js?v=nextstop-14';
import {terrainDetail,bindTerrain,terrainSummary,TERRAIN_SOURCE,profileGeometry} from './terrain.js?v=nextstop-14';
const $=id=>document.getElementById(id);
const state={settings:{...DEFAULTS},draft:{...DEFAULTS},candidates:[],proposals:[],selected:null,network:null,stops:null,density:null,environment:null,terrain:false,ready:false,layers:{rail:true,buses:false,proposals:true,density:false,nature:false}};
let map,mapReady=false,popup,toastTimer;
const range=c=>c[1]<1?'C$'+Math.round(c[0]*1000)+'–'+Math.round(c[1]*1000)+'m':'C$'+c[0].toFixed(1)+'–'+c[1].toFixed(1)+'bn';
const esc=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const candidate=id=>state.candidates.find(c=>c.id===id);
const selected=()=>state.proposals.find(p=>p.id===state.selected);
const sourceLink=key=>'<a href="'+SOURCES[key].url+'" target="_blank" rel="noreferrer">'+esc(SOURCES[key].title)+' <span aria-hidden="true">↗</span></a>';
function toast(text){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4000);}
function fromForm(){const d={};for(const key of Object.keys(DEFAULTS))d[key]=['budget','operations','frequency'].includes(key)?Number($(key).value):$(key).value;return validSettings(d);}
function syncControls(){for(const [k,v] of Object.entries(state.draft))$(k).value=v;updateLabels();}
function updateLabels(){const d=state.draft;$('budget-output').textContent='C$'+d.budget+' billion';$('operations-output').textContent='C$'+d.operations+'m';$('frequency-output').textContent=d.frequency+' minutes';for(const id of ['budget','operations','frequency']){const el=$(id);el.style.setProperty('--progress',(el.value-el.min)/(el.max-el.min)*100+'%');}}
function snapshot(){return {settings:{...state.settings},selectedCorridor:state.selected,proposals:state.proposals.map(p=>({id:p.id,corridor:candidate(p.id).corridor,mode:p.mode,headwayMinutes:p.headway,stops:p.stops.length,km:Number(p.km.toFixed(2)),neighbourhoodDensityContext:candidate(p.id).demographics??null,environmentalScreening:candidate(p.id).environment??null,terrainContext:terrainSummary(candidate(p.id).terrain),constructionBillionsCAD:p.capital.map(x=>Number(x.toFixed(3))),annualOperationsMillionsCAD:Number(p.annual.toFixed(1))})),totals:totals(state.proposals),evidence:'Rule-based exploratory scenarios. Geometry and 2021 census inputs are sourced; neighbourhood density context is derived. Costs and performance are assumptions.',populationEvidenceAvailable:!!state.density,environmentalEvidenceAvailable:!!state.environment,terrainEvidenceAvailable:state.terrain};}
function makeProposal(settings){state.settings=validSettings(settings);state.draft={...state.settings};state.proposals=generate(state.candidates,state.settings);state.selected=state.proposals[0]?.id??null;syncControls();$('pending-message').hidden=true;render();fitMap();return snapshot();}
function selectRoute(id,fly=true){if(!state.proposals.some(p=>p.id===id))return;state.selected=id;render();if(fly&&mapReady)fitCoordinates(candidate(id).coordinates,65);}
function render(){
const sum=totals(state.proposals),p=selected();$('proposal-count').textContent=state.proposals.length;
$('proposal-list').innerHTML=state.proposals.length?state.proposals.map((p,i)=>{const c=candidate(p.id);return '<button class="route-card '+(p.id===state.selected?'selected':'')+'" data-route="'+p.id+'" aria-pressed="'+(p.id===state.selected)+'" style="--route-color:'+c.color+'"><span class="route-number">'+String(i+1).padStart(2,'0')+'</span><span class="route-card-text"><strong>'+c.name+'</strong><span class="route-subtitle">'+c.corridor+' <span>· '+MODES[p.mode].short+'</span></span></span><span class="route-arrow" aria-hidden="true">↗</span></button>';}).join(''):'<div class="empty-state"><span aria-hidden="true">↔</span><strong>Make the most of what’s here.</strong><p>No package fits both budgets under these assumptions. Keep existing service, or increase an allowance to explore upgrades.</p></div>';
const cautious=state.settings.risk==='cautious',tested=sum.capital[cautious?1:0],over=tested>state.settings.budget+.001||sum.annual>state.settings.operations+.001;
$('budget-status').classList.toggle('over',over);
$('budget-status').innerHTML=state.proposals.length?'<div><span>'+(over?'Outside your allowances':cautious?'Upper estimate fits your budget':'Fits at the lower estimate')+'</span><strong>'+Math.round(tested/Math.max(.001,state.settings.budget)*100)+'%</strong></div><div class="budget-track"><i style="width:'+Math.min(100,tested/Math.max(.001,state.settings.budget)*100)+'%"></i></div><small>'+(cautious?'Conservative construction allowance':'Higher costs could exceed your budget')+' · Operations '+sum.annual.toFixed(0)+' / '+state.settings.operations+'m</small>':'';
$('total-cost').textContent=range(sum.capital);$('total-km').textContent=sum.km.toFixed(1)+' km';$('total-annual').textContent='C$'+sum.annual.toFixed(0)+'m';$('total-stops').textContent=state.proposals.length+' corridors · '+sum.stops+' concept stops';
const titles={balanced:'A little more connected.',access:'More of the city, within reach.',speed:'Less time getting across town.',value:'Small moves. New possibilities.'};
$('scenario-title').textContent=state.proposals.length?titles[state.settings.priority]:'Better can start with the basics.';
const headways=[...new Set(state.proposals.map(p=>p.headway))];
$('scenario-subtitle').textContent=state.proposals.length?PRIORITIES[state.settings.priority]+' · '+(headways.length===1?'Every '+headways[0]+' minutes':'Individual service settings'):'No new infrastructure within these allowances.';
if(p){const c=candidate(p.id);$('insight-title').textContent=c.summary;$('insight-summary').textContent=c.why;$('insight-card').style.setProperty('--insight-color',c.color);}else{$('insight-title').textContent='A useful result can be no new line.';$('insight-summary').textContent='Existing services still need maintenance and funding. A bigger map is not always the better next step.';}
for(const id of ['detail-button','compare-button'])$(id).disabled=!p;$('export-button').disabled=!state.ready;updateMap();
}
function mapSources(){
return {lines:{type:'FeatureCollection',features:state.proposals.map((p,i)=>({type:'Feature',properties:{id:p.id,color:candidate(p.id).color,selected:p.id===state.selected?1:0,label:String(i+1).padStart(2,'0')+'  '+candidate(p.id).corridor,mode:MODES[p.mode].short},geometry:{type:'LineString',coordinates:candidate(p.id).coordinates}}))},points:{type:'FeatureCollection',features:state.proposals.flatMap(p=>p.stops.map((s,i)=>({type:'Feature',properties:{id:p.id,color:candidate(p.id).color,name:cleanStopName(s.name),selected:p.id===state.selected?1:0,endpoint:i===0||i===p.stops.length-1},geometry:{type:'Point',coordinates:s.coordinates}})))}};
}
function updateMap(){if(!mapReady)return;const {lines,points}=mapSources();map.getSource('proposals').setData(lines);map.getSource('concept-stops').setData(points);for(const id of ['proposal-glow','proposal-line','proposal-label','concept-stops','concept-stop-label'])map.setLayoutProperty(id,'visibility',state.layers.proposals?'visible':'none');map.setLayoutProperty('existing-rail','visibility',state.layers.rail?'visible':'none');map.setLayoutProperty('existing-streetcars','visibility',state.layers.rail?'visible':'none');map.setLayoutProperty('existing-buses','visibility',state.layers.buses?'visible':'none');if(map.getLayer('density-fill'))for(const id of ['density-fill','density-border'])map.setLayoutProperty(id,'visibility',state.layers.density?'visible':'none');$('density-key').hidden=!state.layers.density;if(map.getLayer('ravine-fill'))for(const id of ['ravine-fill','ravine-border','esa-fill','esa-border','ravine-review-border'])map.setLayoutProperty(id,'visibility',state.layers.nature?'visible':'none');$('nature-key').hidden=!state.layers.nature;document.querySelector('.map-workspace').classList.toggle('nature-active',state.layers.nature);}
function fitCoordinates(coords,pad=45){if(!mapReady||!coords.length)return;const bounds=coords.reduce((b,c)=>b.extend(c),new maplibregl.LngLatBounds(coords[0],coords[0]));const box=$('map').getBoundingClientRect(),heading=document.querySelector('.map-heading').getBoundingClientRect(),overlay=document.querySelector('.map-bottom').getBoundingClientRect();map.fitBounds(bounds,{padding:{top:Math.ceil(Math.min(heading.bottom-box.top+16,box.height*.4)),bottom:Math.ceil(Math.min(box.bottom-overlay.top+12,box.height*.58)),left:pad,right:pad},maxZoom:12,duration:window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:650});}
function fitMap(){if(!mapReady)return;const coords=state.proposals.flatMap(p=>candidate(p.id).coordinates);if(coords.length)fitCoordinates(coords);else map.fitBounds([[-79.65,43.61],[-79.12,43.85]],{padding:50,duration:500});}
function initializeMap(){
try{
if(!window.maplibregl)throw new Error('Map library did not load');
map=new maplibregl.Map({container:'map',style:'https://basemaps.cartocdn.com/gl/positron-gl-style/style.json',center:[-79.39,43.72],zoom:10.3,minZoom:8,maxZoom:16,attributionControl:{compact:true,customAttribution:'TTC and boundary data © City of Toronto'},renderWorldCopies:false,maxBounds:[[-83,41],[-76,46]]});
map.addControl(new maplibregl.NavigationControl({showCompass:false}),'top-right');
map.on('load',()=>{
$('map-unavailable').hidden=true;
if(state.density){
map.addSource('density',{type:'geojson',data:state.density});
map.addLayer({id:'density-fill',type:'fill',source:'density',layout:{visibility:'none'},paint:{'fill-color':['interpolate',['linear'],['get','densityPerKm2'],0,'#ecf3f8',2000,'#c7dbea',5000,'#89b5d1',10000,'#407fa4',20000,'#23506e'],'fill-opacity':.55}});
map.addLayer({id:'density-border',type:'line',source:'density',layout:{visibility:'none'},paint:{'line-color':'#809daf','line-width':.65,'line-opacity':.5}});
map.on('click','density-fill',e=>{if(!state.layers.density||(state.layers.nature&&map.queryRenderedFeatures(e.point,{layers:['ravine-fill','esa-fill']}).length)||map.queryRenderedFeatures(e.point,{layers:['proposal-line','concept-stops']}).length)return;const p=e.features[0].properties;popup?.remove();const content=document.createElement('div');content.className='stop-popup';const title=document.createElement('strong');title.textContent=p.name;const details=document.createElement('p');details.textContent=Number(p.population).toLocaleString()+' people · '+Number(p.densityPerKm2).toLocaleString()+' /km². 2021 census, weighted 25% sample estimate. Density uses full neighbourhood area.';content.append(title,details);popup=new maplibregl.Popup({offset:12}).setLngLat(e.lngLat).setDOMContent(content).addTo(map);});
}
if(state.environment)addEnvironmentLayers(map,state.environment,(lngLat,content)=>{popup?.remove();popup=new maplibregl.Popup({offset:12}).setLngLat(lngLat).setDOMContent(content).addTo(map);});
map.addSource('ttc',{type:'geojson',data:state.network});
map.addLayer({id:'existing-buses',type:'line',source:'ttc',filter:['==',['get','type'],'bus'],layout:{'visibility':'none','line-join':'round'},paint:{'line-color':'#bac4ce','line-width':1,'line-opacity':.65}});
map.addLayer({id:'existing-streetcars',type:'line',source:'ttc',filter:['==',['get','type'],'streetcar'],layout:{'line-join':'round'},paint:{'line-color':'#9da5af','line-width':2,'line-opacity':.7}});
map.addLayer({id:'existing-rail',type:'line',source:'ttc',filter:['==',['get','type'],'rail'],layout:{'line-join':'round','line-cap':'round'},paint:{'line-color':'#9da5af','line-width':3.5,'line-opacity':.9}});
for(const name of ['proposals','concept-stops'])map.addSource(name,{type:'geojson',data:{type:'FeatureCollection',features:[]}});
map.addLayer({id:'proposal-glow',type:'line',source:'proposals',layout:{'line-join':'round','line-cap':'round'},paint:{'line-color':['get','color'],'line-width':['case',['==',['get','selected'],1],15,10],'line-opacity':.12}});
map.addLayer({id:'proposal-line',type:'line',source:'proposals',layout:{'line-join':'round','line-cap':'round'},paint:{'line-color':['get','color'],'line-width':['case',['==',['get','selected'],1],5,3.5],'line-dasharray':[2,1],'line-opacity':.98}});
map.addLayer({id:'proposal-label',type:'symbol',source:'proposals',minzoom:10,layout:{'symbol-placement':'line','text-field':['get','label'],'text-size':12,'text-letter-spacing':.08,'text-offset':[0,-1],'text-font':['Open Sans Semibold']},paint:{'text-color':['get','color'],'text-halo-color':'#ffffff','text-halo-width':3}});
map.addLayer({id:'concept-stops',type:'circle',source:'concept-stops',paint:{'circle-radius':['case',['get','endpoint'],5.5,3.5],'circle-color':'#fff','circle-stroke-color':['get','color'],'circle-stroke-width':2}});
map.addLayer({id:'concept-stop-label',type:'symbol',source:'concept-stops',minzoom:12,layout:{'text-field':['get','name'],'text-size':12,'text-anchor':'left','text-offset':[.8,0],'text-max-width':15,'text-font':['Open Sans Regular']},paint:{'text-color':'#555968','text-halo-color':'#fff','text-halo-width':2}});
for(const id of ['proposal-line','concept-stops']){map.on('mouseenter',id,()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave',id,()=>map.getCanvas().style.cursor='');}
map.on('click','proposal-line',e=>selectRoute(e.features[0].properties.id,false));
map.on('click','concept-stops',e=>{const f=e.features[0];selectRoute(f.properties.id,false);popup?.remove();const content=document.createElement('div');content.className='stop-popup';const strong=document.createElement('strong');strong.textContent=f.properties.name;const p=document.createElement('p');p.textContent='Concept stop · Placement requires design review';content.append(strong,p);popup=new maplibregl.Popup({offset:12}).setLngLat(f.geometry.coordinates).setDOMContent(content).addTo(map);});
mapReady=true;updateMap();fitMap();
});
map.on('error',event=>{if(!mapReady&&event.error?.message?.includes('Failed'))$('map-unavailable').hidden=false;});
}catch(error){$('map-unavailable').hidden=false;console.warn('Background map unavailable',error.message);}
}
function densityDetail(c){
const d=c.demographics;if(!d)return '<div class="density-evidence"><h3>Population evidence unavailable</h3><p>This proposal currently uses stop coverage as a fallback. Reload to retry the census dataset.</p></div>';
const coverage=Math.round(d.coverageFraction*100);
return '<div class="density-evidence"><span class="eyebrow">2021 CENSUS · NEIGHBOURHOOD CONTEXT</span><strong>~'+(Math.round(d.densityPerKm2/100)*100).toLocaleString()+' people / km²</strong><p>Average neighbourhood density around this corridor, weighted by overlap with an 800 m straight-line band.</p><p class="field-help">Uses weighted 25% sample population estimates and full polygon area. Neighbourhood averages hide local variation. This is not a walking catchment, current population estimate or rider forecast.</p>'+(coverage<99?'<p class="coverage-note">Toronto data covers '+coverage+'% of this band. The remainder, including areas outside Toronto, is excluded and is not treated as zero population.</p>':'')+'<details><summary>Neighbourhoods contributing to this context</summary><ul>'+d.neighbourhoods.map(n=>'<li>'+esc(n.name)+' <span>'+Math.round(n.densityPerKm2).toLocaleString()+' /km²</span></li>').join('')+'</ul></details>'+sourceLink('population')+'</div>';
}
function openDetail(){
const p=selected();if(!p)return;const c=candidate(p.id);
$('detail-content').innerHTML='<div class="dialog-top"><span class="eyebrow" style="color:'+c.color+'">'+c.area+' · CONNECTION '+(state.proposals.indexOf(p)+1)+'</span><button class="close-dialog" aria-label="Close connection details">×</button></div><h2 id="detail-title">'+c.corridor+'</h2><p>'+c.summary+'</p><div class="detail-stats"><div><small>Concept length</small><strong>'+p.km.toFixed(1)+' km</strong></div><div><small>Construction range</small><strong>'+range(p.capital)+'</strong></div></div><div class="detail-controls"><label for="detail-mode">Transit mode</label><select id="detail-mode">'+Object.entries(MODES).map(([id,m])=>'<option value="'+id+'" '+(id===p.mode?'selected':'')+'>'+m.name+'</option>').join('')+'</select><label for="detail-frequency">Departures</label><select id="detail-frequency">'+Array.from({length:13},(_,i)=>i+3).map(n=>'<option value="'+n+'" '+(n===p.headway?'selected':'')+'>Every '+n+' minutes</option>').join('')+'</select><label for="detail-spacing">Stops</label><select id="detail-spacing">'+[['local','More local stops'],['balanced','Balanced spacing'],['express','Fewer stops, longer walks']].map(([id,name])=>'<option value="'+id+'" '+(id===p.spacing?'selected':'')+'>'+name+'</option>').join('')+'</select></div><button class="generate-button" id="apply-adjustment">Apply to this connection <span aria-hidden="true">→</span></button>'+densityDetail(c)+terrainDetail(c,cleanStopName(c.stops[0].name),cleanStopName(c.stops.at(-1).name))+environmentDetail(c,p.mode)+'<h3>Why explore it?</h3><p>'+c.why+'</p><div class="case-card"><span class="eyebrow">A LESSON FROM '+c.case.toUpperCase()+'</span><p>'+c.lesson+'</p>'+sourceLink(c.case)+'</div><h3>What still needs an answer</h3><p>'+c.caution+'</p><div class="review-chips">'+c.review.map(x=>'<span>'+x+'</span>').join('')+'</div><h3>Concept stops <span class="small-badge">'+p.stops.length+'</span></h3><p class="field-help">Selected from existing bus stop locations. These are not approved station sites.</p><ol class="stop-list" style="--route-color:'+c.color+'">'+p.stops.map(s=>'<li>'+esc(cleanStopName(s.name))+'</li>').join('')+'</ol><p class="field-help">'+c.confidence+'. '+sourceLink('ttc')+'</p>';
$('detail-dialog').showModal();bindTerrain(c.terrain);
$('detail-mode').addEventListener('change',()=>{$('detail-content').querySelector('.environment-evidence').outerHTML=environmentDetail(c,$('detail-mode').value);});
$('apply-adjustment').addEventListener('click',()=>{const updated=evaluate(c,$('detail-mode').value,{...state.settings,frequency:Number($('detail-frequency').value),spacing:$('detail-spacing').value});state.proposals=state.proposals.map(old=>old.id===c.id?updated:old);render();$('detail-dialog').close();toast(c.corridor+' updated. Check the package against your allowances.');});
}
function openCompare(){
const p=selected();if(!p)return;const c=candidate(p.id);const options=Object.keys(MODES).map(m=>evaluate(c,m,{...state.settings,frequency:p.headway,spacing:p.spacing}));
$('comparison-content').innerHTML='<div class="comparison-heading"><strong>'+c.corridor+'</strong><span>'+c.km.toFixed(1)+' km · Every '+p.headway+' minutes</span></div><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Alternative</th><th>Construction</th><th>Annual operations</th><th>Stops</th><th>Modelled journey*</th><th></th></tr></thead><tbody><tr class="baseline-row"><td>Existing bus assumption</td><td>No new investment</td><td>Not modelled</td><td>'+c.stops.length+'</td><td>'+Math.round(p.baseMinutes)+' min</td><td></td></tr>'+options.map(o=>'<tr class="'+(o.mode===p.mode?'chosen-row':'')+'"><td><strong>'+MODES[o.mode].name+'</strong>'+(o.mode===p.mode?'<small>In your proposal</small>':'')+'</td><td>'+range(o.capital)+'</td><td>C$'+o.annual.toFixed(0)+'m</td><td>'+o.stops.length+'</td><td>'+Math.round(o.journey)+' min</td><td><button class="table-choose" data-choose-mode="'+o.mode+'">'+(o.mode===p.mode?'Selected':'Use this')+'</button></td></tr>').join('')+'</tbody></table></div><p class="comparison-footnote">*End-to-end running time plus assumed average wait. Excludes walking, transfers, traffic variability and crowding. These are model outputs, not observed or forecast journey times. Fewer stops can make the model faster while making real journeys harder for some people.</p><div class="method-callout"><strong>A new rail line is only one possibility.</strong><p>Bus priority is always considered, including when you express a preference for rail. If no investment fits both allowances, the generator returns no construction package. Budgets are hypothetical, not available government funds.</p></div>';
$('compare-dialog').showModal();
}
function exportProposal(){
const features=state.proposals.flatMap(p=>[{type:'Feature',properties:{name:candidate(p.id).corridor,mode:MODES[p.mode].name,headway_minutes:p.headway,construction_range_billions_CAD:p.capital,evidence:'Exploratory concept; follows TTC bus geometry. Not an official alignment.'},geometry:{type:'LineString',coordinates:candidate(p.id).coordinates}},...p.stops.map(s=>({type:'Feature',properties:{name:s.name,corridor:candidate(p.id).corridor,status:'concept_stop'},geometry:{type:'Point',coordinates:s.coordinates}}))]);
const data={type:'FeatureCollection',name:'Nextstop Toronto proposal',generated_at:new Date().toISOString(),model_version:'0.4',...snapshot(),attribution:'Contains information licensed under the Open Government Licence – Toronto.',source:SOURCES.ttc.url,populationSource:SOURCES.population.url,environmentSources:ENVIRONMENT_SOURCES,terrainSource:TERRAIN_SOURCE,terrainProfiles:state.proposals.map(p=>({id:p.id,profile:candidate(p.id).terrain??null})),environmentMethod:'2D line/polygon overlap using valid source polygons and a 50 m proximity search. Invalid ravine polygons are excluded from measured overlap and shown provisionally; affected corridors are marked incomplete. Historical July 2019 ravine file; March 2026 ESA file. Toronto only. Not an impact calculation, legal setback or approval.',populationMethod:'Weighted 2021 25% sample estimates divided by full neighbourhood polygon area. Corridor context weights those densities by intersections with an 800 m straight-line buffer. Not a walk catchment or ridership estimate.',limitations:'Not a ridership forecast, financial assessment, environmental clearance or engineering plan. Costs and speeds are illustrative assumptions.',features};
const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/geo+json'}));const link=document.createElement('a');link.href=url;link.download='nextstop-toronto-proposal.geojson';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Proposal downloaded with its assumptions and sources.');
}
function setupEvents(){
$('proposal-settings').addEventListener('input',()=>{state.draft=fromForm();updateLabels();$('pending-message').hidden=false;});
$('proposal-settings').addEventListener('submit',event=>{event.preventDefault();if(!state.ready)return;makeProposal(fromForm());toast(state.proposals.length?state.proposals.length+' connections generated.':'No new construction fits these allowances.');});
$('proposal-list').addEventListener('click',event=>{const button=event.target.closest('[data-route]');if(button)selectRoute(button.dataset.route);});
$('method-button').addEventListener('click',()=>$('method-dialog').showModal());
$('detail-button').addEventListener('click',openDetail);$('compare-button').addEventListener('click',openCompare);$('fit-map').addEventListener('click',fitMap);$('export-button').addEventListener('click',exportProposal);
document.addEventListener('click',event=>{const close=event.target.closest('.close-dialog');if(close)close.closest('dialog').close();const mode=event.target.closest('[data-choose-mode]');if(mode){const old=selected(),c=candidate(old.id);const updated=evaluate(c,mode.dataset.chooseMode,{...state.settings,frequency:old.headway,spacing:old.spacing});state.proposals=state.proposals.map(p=>p.id===old.id?updated:p);render();$('compare-dialog').close();toast(MODES[updated.mode].name+' applied to '+c.corridor+'.');}});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const box=dialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)dialog.close();}});
for(const key of ['rail','buses','proposals','density','nature'])$('toggle-'+key).addEventListener('click',()=>{state.layers[key]=!state.layers[key];$('toggle-'+key).setAttribute('aria-pressed',String(state.layers[key]));$('toggle-'+key).classList.toggle('active',state.layers[key]);if((key==='density'||key==='nature')&&state.layers[key]){const other=key==='density'?'nature':'density';state.layers[other]=false;$('toggle-'+other).setAttribute('aria-pressed','false');$('toggle-'+other).classList.remove('active');}updateMap();if(key==='density'||key==='nature')fitMap();});
}
function registerTools(){
const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
const schema={type:'object',properties:{budget:{type:'number',minimum:0,maximum:25,multipleOf:.5},operations:{type:'number',minimum:0,maximum:500,multipleOf:10},priority:{type:'string',enum:Object.keys(PRIORITIES)},frequency:{type:'integer',minimum:3,maximum:15},spacing:{type:'string',enum:['local','balanced','express']},preference:{type:'string',enum:['auto','surface','brt','lrt','metro']},risk:{type:'string',enum:['cautious','ambitious']}},additionalProperties:false};
for(const tool of [
{name:'read_toronto_proposal',description:'Read the current generated Toronto proposal, settings and explicit evidence limitations.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>snapshot()},
{name:'generate_toronto_proposal',description:'Generate a Toronto proposal and update the visible map with the supplied assumptions. Replaces current adjustments.',inputSchema:schema,annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!state.ready)throw new Error('Toronto data is not ready');return makeProposal(validSettings(input));}}
])try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
}
async function init(){
initializeTravel();
setupEvents();syncControls();$('source-links').innerHTML=['ttc','population','neighbourhoods','tts','tokyo','seoul','beijing','singapore','greenbelt','cost'].map(sourceLink).join('');
try{const responses=await Promise.all(['data/ttc-network.json','data/ttc-stops.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw new Error('Transit dataset did not load');return r.json();})));[state.network,state.stops]=responses;state.candidates=buildCandidates(...responses);
try{const [density,evidence]=await Promise.all(['data/neighbourhood-density.json','data/corridor-demographics.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw new Error('Population dataset did not load');return r.json();})));if(density.features?.length!==158||state.candidates.some(c=>!Number.isFinite(evidence[c.id]?.densityPerKm2)))throw new Error('Population evidence is incomplete');state.density=density;state.candidates.forEach(c=>c.demographics=evidence[c.id]);$('toggle-density').disabled=false;}catch(error){$('population-status').hidden=false;console.warn('Population evidence unavailable',error.message);}
try{const [areas,evidence]=await Promise.all(['data/environment-areas.json','data/corridor-environment.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw new Error('Environmental dataset did not load');return r.json();})));if(areas.features?.length!==946||state.candidates.some(c=>!Number.isFinite(evidence[c.id]?.ravine?.overlapMetres)||!Number.isFinite(evidence[c.id]?.esa?.overlapMetres)))throw new Error('Environmental screening is incomplete');state.environment=areas;state.candidates.forEach(c=>c.environment=evidence[c.id]);$('toggle-nature').disabled=false;}catch(error){$('environment-status').hidden=false;console.warn('Environmental evidence unavailable',error.message);}
try{const response=await fetch('data/corridor-terrain.json');if(!response.ok)throw new Error('Terrain dataset did not load');const evidence=await response.json();for(const c of state.candidates){if(!evidence[c.id]||evidence[c.id].sourceYear!==2023)throw new Error('Terrain coverage is incomplete');profileGeometry(evidence[c.id].samples);}state.candidates.forEach(c=>c.terrain=evidence[c.id]);state.terrain=true;}catch(error){$('terrain-status').hidden=false;console.warn('Terrain evidence unavailable',error.message);}
state.ready=true;makeProposal(DEFAULTS);registerTools();initializeMap();}
catch(error){$('proposal-list').innerHTML='<div class="empty-state"><strong>Toronto’s data could not load.</strong><p>Please reload to try again. No proposals have been generated.</p></div>';$('generate').disabled=true;console.error(error);}
}
init();
